{"path":"/app/create_availability.py","content":"#!/usr/bin/env python3
"""Parse raw friend schedules into all_availability.json."""

import json
import re
from datetime import date, datetime, timedelta
from pathlib import Path

BASE = Path('/app')
YEAR_START = date(2025, 1, 1)
YEAR_END = date(2025, 12, 31)

MONTHS = {
    'January': 1, 'February': 2, 'March': 3, 'April': 4,
    'May': 5, 'June': 6, 'July': 7, 'August': 8,
    'September': 9, 'October': 10, 'November': 11, 'December': 12,
}


def parse_iso(s: str) -> date:
    return datetime.strptime(s, '%Y-%m-%d').date()


def fmt(d: date) -> str:
    return d.strftime('%Y-%m-%d')


def complement(busy_ranges, start=YEAR_START, end=YEAR_END):
    busy = sorted(busy_ranges)
    free = []
    cursor = start
    for b_start, b_end in busy:
        if b_end < cursor:
            continue
        if b_start > cursor:
            free.append((cursor, b_start - timedelta(days=1)))
        cursor = max(cursor, b_end + timedelta(days=1))
    if cursor <= end:
        free.append((cursor, end))
    return free


def ranges_to_json(ranges):
    return [{'start': fmt(s), 'end': fmt(e)} for s, e in ranges if s <= e]


def parse_alice():
    text = (BASE / 'alice_schedule.txt').read_text()
    busy = []
    for start, end in re.findall(r'UNAVAILABLE:\s*(\d{4}-\d{2}-\d{2}) to (\d{4}-\d{2}-\d{2})', text):
        busy.append((parse_iso(start), parse_iso(end)))
    return complement(busy)


def parse_bob():
    text = (BASE / 'bob_schedule.txt').read_text()
    off_dates = []
    for line in text.splitlines():
        m = re.match(r'SHIFT:\s*(\d{4}-\d{2}-\d{2}),off,', line)
        if m:
            off_dates.append(parse_iso(m.group(1)))
    off_dates = sorted(off_dates)
    ranges = []
    if off_dates:
        start = prev = off_dates[0]
        for d in off_dates[1:]:
            if d == prev + timedelta(days=1):
                prev = d
            else:
                ranges.append((start, prev))
                start = prev = d
        ranges.append((start, prev))
    return ranges


def parse_charlie():
    text = (BASE / 'charlie_schedule.txt').read_text()
    busy = []
    # January 2025 - May 2025 means full inclusive months.
    busy.append((date(2025, 1, 1), date(2025, 5, 31)))
    for month, start_day, end_day, year in re.findall(r'(June|July|August)\s+(\d{1,2})-(\d{1,2}),\s*(\d{4})', text):
        y = int(year)
        m = MONTHS[month]
        busy.append((date(y, m, int(start_day)), date(y, m, int(end_day))))
    return complement(busy)


def parse_dana():
    text = (BASE / 'dana_schedule.txt').read_text()
    busy = []
    for start, end in re.findall(r'BUSY:\s*(\d{4}-\d{2}-\d{2}) to (\d{4}-\d{2}-\d{2})', text):
        busy.append((parse_iso(start), parse_iso(end)))
    return complement(busy)


def main():
    data = {
        'alice': ranges_to_json(parse_alice()),
        'bob': ranges_to_json(parse_bob()),
        'charlie': ranges_to_json(parse_charlie()),
        'dana': ranges_to_json(parse_dana()),
    }
    (BASE / 'all_availability.json').write_text(json.dumps(data, indent=2) + '\n')
    print(json.dumps(data, indent=2))


if __name__ == '__main__':
    main()
"}

